#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
// Include the header generated by bison/yacc
// This header defines the token types and the YYSTYPE union
#include "parser.tab.h"
#include "ast.h" // Include our AST node definitions
#include "symbol_table.h" // Include our Symbol Table definitions
#include "codegen.h"

// Manually declare yyparse because it might be missing from your parser.tab.h
extern int yyparse(void);

// Bison requires yylval to be declared extern YYSTYPE yylval;
// It's usually declared in parser.tab.h, but explicitly declaring it here
// ensures it's visible to yylex.
extern YYSTYPE yylval;

char* yytext;
int yylineno = 1;

// Declare the AST root defined in parser.y
extern AST_Node* program_ast_root;

// Declare the global Symbol Table defined in parser.y
extern SymbolTable* global_symbol_table;


// A simple counter for generating temporary variable names
static int temp_counter = 0;

// Function to generate a new temporary variable name
char* new_temp() {
    char* temp_name = (char*)malloc(20 * sizeof(char)); // Allocate space for "t" + number + null terminator
    sprintf(temp_name, "t%d", temp_counter++);
    return temp_name;
}


void skip_whitespace() {
    int ch;
    while ((ch = getchar()) != EOF) {
        if (ch == '\n') yylineno++;
        if (!isspace(ch)) {
            ungetc(ch, stdin);
            break;
        }
    }
}

int yylex() {
    static char buffer[100]; // Consider increasing buffer size for longer tokens
    int ch, i = 0;

    skip_whitespace();

    ch = getchar();
    if (ch == EOF) return 0; // Return 0 for EOF

    // Identifiers and Keywords
    if (isalpha(ch) || ch == '_') { // Identifiers can start with _
        buffer[i++] = ch;
        while ((ch = getchar()) != EOF && (isalnum(ch) || ch == '_'))
            buffer[i++] = ch;
        buffer[i] = '\0';
        ungetc(ch, stdin); // Put the character that stopped the loop back
        yytext = buffer;

        // Match keywords defined in parser.y
        if (strcmp(buffer, "def") == 0) {
            printf("Token: DEF, Value: %s\n", yytext);
            return DEF; // Return DEF token
        } else if (strcmp(buffer, "print") == 0) {
            printf("Token: PRINT, Value: %s\n", yytext);
            return PRINT; // Return PRINT token
        } else if (strcmp(buffer, "return") == 0) {
            printf("Token: RETURN, Value: %s\n", yytext);
            return RETURN; // Return RETURN token
        }

        printf("Token: IDENTIFIER, Value: %s\n", yytext);
        // Set the semantic value for IDENTIFIER to a duplicate of the string
        yylval.string_value = strdup(yytext); // Corrected typo: string_value
        return IDENTIFIER; // Return IDENTIFIER token
    }

    // Numbers (NUMBER or INVALID like 13a)
    if (isdigit(ch)) {
        buffer[i++] = ch;
        int isFloat = 0;
        int isInvalid = 0; // Flag to indicate if the whole sequence is invalid

        // Read digits and a single optional dot
        while ((ch = getchar()) != EOF) {
            if (isdigit(ch)) {
                buffer[i++] = ch;
            } else if (ch == '.') {
                if (isFloat) { // Already saw a dot
                    isInvalid = 1; // Invalid number (multiple dots)
                    buffer[i++] = ch; // Consume the extra dot as part of the invalid sequence
                    // Keep reading subsequent characters to consume the whole invalid token
                } else {
                    isFloat = 1;
                    buffer[i++] = ch;
                }
            } else if (isalnum(ch) || ch == '_') {
                // If we see an alphanumeric or underscore after digits, it's likely an invalid number like 13a
                isInvalid = 1;
                buffer[i++] = ch;
                // Keep reading subsequent characters to consume the whole invalid token
            }
            else {
                // If it's not a digit, dot, alphanumeric, or underscore, it's the end of the token
                ungetc(ch, stdin);
                break;
            }
        }
        buffer[i] = '\0';
        yytext = buffer;

        // Check if the sequence is invalid
        // A number cannot end with a dot (e.g., "12.")
        if (buffer[i-1] == '.') {
             isInvalid = 1;
        }

        if (isInvalid) {
             printf("Token: INVALID, Value: %s\n", yytext);
             // For invalid tokens that are sequences, you might want to
             // free the duplicated string if you used strdup here.
             return INVALID; // Return INVALID token
        }

        // If the number is valid based on our checks
        printf("Token: NUMBER, Value: %s\n", yytext);
        // Set the semantic value for NUMBER
        if (isFloat) {
            yylval.float_val = atof(yytext); // Convert string to float
        } else {
            yylval.float_val = atoi(yytext); // Convert string to int, store as float for simplicity
        }
        return NUMBER; // Return NUMBER token
    }

    // Single character tokens
    // Note: These are checked *after* identifier and number checks,
    // so characters like '+' or '=' won't be mistaken for identifiers.
    switch (ch) {
        case '=': printf("Token: EQUALS, Value: %c\n", ch); return EQUALS; // Return EQUALS token
        case '+': printf("Token: PLUS, Value: %c\n", ch); return PLUS;   // Return PLUS token
        case '-': printf("Token: MINUS, Value: %c\n", ch); return MINUS;  // Return MINUS token
        case '*': printf("Token: TIMES, Value: %c\n", ch); return TIMES;  // Return TIMES token
        case '/': printf("Token: DIVIDE, Value: %c\n", ch); return DIVIDE; // Return DIVIDE token
        case '(': printf("Token: LPAREN, Value: %c\n", ch); return LPAREN; // Return LPAREN token
        case ')': printf("Token: RPAREN, Value: %c\n", ch); return RPAREN; // Return RPAREN token
        // Removed cases for ',' and ':' as they are not in parser.y tokens
        default:
            // If it's not whitespace, part of an identifier/keyword, number, or known single char token
            buffer[0] = ch;
            buffer[1] = '\0';
            yytext = buffer;
            printf("Token: INVALID, Value: %s\n", yytext);
            return INVALID; // Return INVALID token
    }
}

// --- AST Printing Function ---
void print_indent(int indent) {
    for (int i = 0; i < indent; i++) {
        printf("  "); // Use two spaces per indent level
    }
}

void print_ast(AST_Node* node, int indent) {
    if (node == NULL) {
        return;
    }

    print_indent(indent);

    switch (node->type) {
        case NODE_PROGRAM:
            printf("PROGRAM\n");
            // Added block for variable scope
            {
                StatementList* current = node->statements;
                while(current != NULL) {
                    print_ast(current->statement, indent + 1);
                    current = current->next;
                }
            } // End of block
            break;
        case NODE_NUMBER:
            // Assuming numbers are stored as floats in the AST value union
            printf("NUMBER: %f\n", node->value.float_value);
            break;
        case NODE_IDENTIFIER:
            printf("IDENTIFIER: %s\n", node->value.string_value); // Corrected typo: string_value
            break;
        case NODE_BINARY_OP:
            printf("BINARY_OP: ");
            switch (node->value.int_value) { // op_type is stored in int_value
                case PLUS: printf("+\n"); break;
                case MINUS: printf("-\n"); break;
                case TIMES: printf("*\n"); break;
                case DIVIDE: printf("/\n"); break;
                default: printf("UNKNOWN\n"); break;
            }
            print_ast(node->left, indent + 1);
            print_ast(node->right, indent + 1);
            break;
        case NODE_ASSIGNMENT:
            printf("ASSIGNMENT\n");
            print_indent(indent + 1);
            printf("Target:\n");
            print_ast(node->identifier, indent + 2);
            print_indent(indent + 1);
            printf("Value:\n");
            print_ast(node->expression, indent + 2);
            break;
        case NODE_PRINT_STATEMENT:
            printf("PRINT_STATEMENT\n");
            print_ast(node->expression, indent + 1);
            break;
        default:
            printf("UNKNOWN_NODE_TYPE\n");
            break;
    }
}

// --- Intermediate Code Generation Function ---
// This function traverses the AST and generates TAC.
// It returns the "address" (variable name or literal) where the result of the expression is stored.
char* generate_ic(AST_Node* node) {
    if (node == NULL) {
        return NULL;
    }

    char* left_addr = NULL;
    char* right_addr = NULL;
    char* result_addr = NULL;

    switch (node->type) {
        case NODE_PROGRAM:
            {
                StatementList* current = node->statements;
                while(current != NULL) {
                    generate_ic(current->statement); // Generate IC for each statement
                    current = current->next;
                }
            }
            result_addr = strdup("PROGRAM_END"); // Indicate end of program IC
            break;

        case NODE_NUMBER:
            // For a number literal, the "address" is the literal value itself (as a string)
            result_addr = (char*)malloc(50 * sizeof(char)); // Sufficient size for float string
            sprintf(result_addr, "%f", node->value.float_value);
            break;

        case NODE_IDENTIFIER:
            // For an identifier, the "address" is the identifier name
            result_addr = strdup(node->value.string_value);
            break;

        case NODE_BINARY_OP:
            // Generate IC for left and right sub-expressions
            left_addr = generate_ic(node->left);
            right_addr = generate_ic(node->right);

            // Generate a new temporary variable for the result
            result_addr = new_temp();

            // Determine the operator string
            char* op_str;
            switch (node->value.int_value) {
                case PLUS: op_str = "+"; break;
                case MINUS: op_str = "-"; break;
                case TIMES: op_str = "*"; break;
                case DIVIDE: op_str = "/"; break;
                default: op_str = "UNKNOWN_OP"; break;
            }

            // Print the TAC instruction: result = operand1 op operand2
            printf("  %s = %s %s %s\n", result_addr, left_addr, op_str, right_addr);

            // Free temporary addresses used for operands if they were generated temps
            // Note: This simple freeing assumes the returned addresses are only used immediately.
            // A more robust IC generation would manage temporary variable lifetimes.
            if (left_addr && left_addr[0] == 't') free(left_addr);
            if (right_addr && right_addr[0] == 't') free(right_addr);

            break;

        case NODE_ASSIGNMENT:
            // Added block for variable scope
            {
                // Generate IC for the expression on the right-hand side
                char* expr_addr = generate_ic(node->expression);

                // The target is the identifier on the left-hand side
                char* target_name = node->identifier->value.string_value;

                // Print the TAC instruction: target = value
                printf("  %s = %s\n", target_name, expr_addr);

                // The result of an assignment is the target variable itself (optional, depending on IR design)
                result_addr = strdup(target_name);

                // Free the temporary address used for the expression if it was a generated temp
                if (expr_addr && expr_addr[0] == 't') free(expr_addr);
            } // End of block
            break;

        case NODE_PRINT_STATEMENT:
            // Added block for variable scope
            {
                // Generate IC for the expression to be printed
                char* print_expr_addr = generate_ic(node->expression);

                // Print the TAC instruction: PRINT value
                printf("  PRINT %s\n", print_expr_addr);

                // Free the temporary address used for the expression if it was a generated temp
                if (print_expr_addr && print_expr_addr[0] == 't') free(print_expr_addr);
            } // End of block
            result_addr = strdup("PRINT_COMPLETE"); // Indicate print operation
            break;

        default:
            // Handle unknown node types or nodes that don't generate IC directly
            result_addr = strdup("UNKNOWN_NODE");
            break;
    }

    // Note: We are returning dynamically allocated strings (temp names or duplicated identifiers/literals).
    // Proper memory management is needed to free these strings later if they are not used as results.
    // In this simple example, they are mostly printed and then some are freed.
    return result_addr; // Return the address of the result
}


// --- Memory Deallocation Function ---
// It's important to free the memory allocated for the AST nodes

// The main function to start the parsing process
int main() {
    printf("Starting parsing...\n");

    // Create the global symbol table before parsing starts
    global_symbol_table = create_symbol_table(100);
    if (global_symbol_table == NULL) {
        fprintf(stderr, "Failed to create symbol table.\n");
        return EXIT_FAILURE;
    }

    // Call yyparse() to begin parsing the input
    int result = yyparse();

    if (result == 0) {
        printf("Parsing successful.\n");
        printf("\n--- Abstract Syntax Tree ---\n");
        print_ast(program_ast_root, 0);
        printf("----------------------------\n");

        printf("\n--- Symbol Table Contents ---\n");
        print_symbol_table(global_symbol_table);
        printf("-----------------------------\n");

        printf("\n--- Intermediate Code (Three-Address Code) ---\n");
        generate_ic(program_ast_root);
        printf("--------------------------------------------\n");

        // CALL CODEGEN HERE:
        printf("\n--- Assembly Code ---\n");
        codegen(); // Call the codegen function
        printf("-----------------------\n");

        // Free the allocated AST memory after printing and IC generation
        free_ast(program_ast_root);

    } else {
        // If yyparse() returns a non-zero value (indicating an error)
        printf("Parsing failed.\n");
    }

    // Destroy the symbol table at the end of the program
    destroy_symbol_table(global_symbol_table);

    return result;
}